window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dcbcec13fce757b8"]={"versions": [{"id": "FIG-dcbcec13fce757b8", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Datentypen der AUTOSAR E2E-Bibliothek (Profile 11). Das Diagramm stellt eine Datenstruktur zur Verwaltung des internen Senderzustands für den Schutzmechanismus bereit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die Struktur <code>E2E_P11ProtectStateType</code> im Namensraum <code>E2E::E2E_P11Types</code> mit dem Stereotyp <code>«structure»</code>. Sie kapselt das öffentliche Attribut:</p>\n<ul class=\"fig-list\"><li><code>+ Counter :uint8</code>: Sequenzzähler zur Verfolgung übertragener Datenfolgen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datentypschema ohne dynamische Sequenzabläufe. Die Struktur dient als Zustandsspeicher, der von E2E-Profile-11-Schutzfunktionen (Protect) instanziiert, gelesen und je Aufrufzyklus inkrementiert bzw. aktualisiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinition für AUTOSAR Classic und Adaptive Platform E2E-Schutzimplementierungen. Entwickler müssen sicherstellen, dass die Struktur persistent über aufeinanderfolgende Sendeaufrufe beibehalten wird, um eine lückenlose Sequenzzählerfortschreibung gemäß Profile-11-Spezifikation zu gewährleisten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-60546d34df4c76e7", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Datentypen der AUTOSAR E2E-Bibliothek (Profile 11). Das Diagramm stellt eine Datenstruktur zur Verwaltung des internen Senderzustands für den Schutzmechanismus bereit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die Struktur <code>E2E_P11ProtectStateType</code> im Namensraum <code>E2E_P11Types</code> mit dem Stereotyp <code>«structure»</code>. Sie kapselt das öffentliche Attribut:</p>\n<ul class=\"fig-list\"><li><code>+ Counter: uint8</code>: Sequenzzähler zur Verfolgung übertragener Datenfolgen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datentypschema ohne dynamische Sequenzabläufe. Die Struktur dient als Zustandsspeicher, der von E2E-Profile-11-Schutzfunktionen (Protect) instanziiert, gelesen und je Aufrufzyklus inkrementiert bzw. aktualisiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinition für AUTOSAR Classic und Adaptive Platform E2E-Schutzimplementierungen. Entwickler müssen sicherstellen, dass die Struktur persistent über aufeinanderfolgende Sendeaufrufe beibehalten wird, um eine lückenlose Sequenzzählerfortschreibung gemäß Profile-11-Spezifikation zu gewährleisten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f93c299ed2818579", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Datentypen der AUTOSAR E2E-Bibliothek (Profile 11). Das Diagramm stellt eine Datenstruktur zur Verwaltung des internen Senderzustands für den Schutzmechanismus bereit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die Struktur <code>E2E_P11ProtectStateType</code> im Namensraum <code>E2E_P11Types</code> mit dem Stereotyp <code>«structure»</code>. Sie kapselt das öffentliche Attribut:</p>\n<ul class=\"fig-list\"><li><code>+ Counter: uint8</code>: Sequenzzähler zur Verfolgung übertragener Datenfolgen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datentypschema ohne dynamische Sequenzabläufe. Die Struktur dient als Zustandsspeicher, der von E2E-Profile-11-Schutzfunktionen (Protect) instanziiert, gelesen und je Aufrufzyklus inkrementiert bzw. aktualisiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinition für AUTOSAR Classic und Adaptive Platform E2E-Schutzimplementierungen. Entwickler müssen sicherstellen, dass die Struktur persistent über aufeinanderfolgende Sendeaufrufe beibehalten wird, um eine lückenlose Sequenzzählerfortschreibung gemäß Profile-11-Spezifikation zu gewährleisten.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-dcbcec13fce757b8", "to": "FIG-60546d34df4c76e7", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Paketpfad der Datenstruktur: <code>E2E::E2E_P11Types::E2E_P11ProtectStateType</code> verkürzt zu <code>E2E_P11Types::E2E_P11ProtectStateType</code> (Wegfall des übergeordneten Namespace-Präfixes <code>E2E::</code>).\n</li><li>Elementbeschriftung: Leerraum vor dem Doppelpunkt bei <code>+ Counter :uint8</code> entfernt zu <code>+ Counter: uint8</code>.\n</li></ul>"}, {"from": "FIG-60546d34df4c76e7", "to": "FIG-f93c299ed2818579", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
